from fastapi import FastAPI, Depends
order_state = {42: {'order_id': 42, 'quantity': 5}, 43: {'order_id': 43, 'quantity': 0}, 44: {'order_id': 44, 'quantity': 3}, 45: {'order_id': 45, 'quantity': 10}, 46: {'order_id': 46, 'quantity': 1}, 7: {'order_id': 7, 'quantity': 2}}

class OrderStateAdapter:
    def quantity(self, order_id: int) -> int:
        return order_state[order_id]["quantity"]

adapter = OrderStateAdapter()

def requested_quantity(quantity: int) -> int:
    return quantity

app = FastAPI()

def accepts_quantity(requested: int, stored: int) -> bool:
    return requested <= stored

@app.get("/orders/{order_id}")
def decide_order(order_id: int, quantity: int = Depends(requested_quantity)):
    stored = adapter.quantity(order_id)
    return accepts_quantity(quantity, stored)

from fastapi import FastAPI, BackgroundTasks
follow_ups = []

def order_follow_up(order_id: str):
    """Small optional, process-local synthetic effect; losing it is acceptable."""
    follow_ups.append(order_id)

app = FastAPI()

@app.post("/orders")
def create_order(background_tasks: BackgroundTasks):
    order_id = "42"
    background_tasks.add_task(order_follow_up, order_id)
    # Process-local optional work; this would NOT meet guaranteed completion.
    return {"order_id": order_id}

# Supplied registration inspection, unchanged.
def inspect_registration(order_id):
    import inspect
    tasks = BackgroundTasks()
    follow_ups.clear()
    response = create_order(tasks)
    return {"response": response, "before_response_follow_ups": list(follow_ups), "tasks": [{"callable": t.func.__name__, "args": list(t.args)} for t in tasks.tasks], "durability_annotation": "NOT meet guaranteed completion" in inspect.getsource(create_order)}

from typing import Annotated
from fastapi import FastAPI, Depends
app = FastAPI()

def pagination(page: int, page_size: int) -> dict[str, int]:
    return {"page": page, "page_size": page_size}

def order_options(pagination_value: Annotated[dict[str, int], Depends(pagination)]) -> dict[str, int]:
    return pagination_value

@app.get("/orders")
def orders(options: Annotated[dict[str, int], Depends(order_options)]):
    return options

# Supplied graph inspector; leave unchanged.
def inspect_edge(part):
    import inspect
    fn = order_options if part == "order_options" else orders
    parameter = next(iter(inspect.signature(fn).parameters.values()))
    metadata = getattr(parameter.annotation, "__metadata__", ())
    dependency = next((x.dependency for x in metadata if hasattr(x, "dependency")), None)
    return getattr(dependency, "__name__", None)
